#include <stdio.h>

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int col_sum[1005] = {0};

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int val;
            scanf("%d", &val);
            col_sum[j] += val;
        }
    }

    int min_val = col_sum[0];
    for (int j = 1; j < m; j++) {
        if (col_sum[j] < min_val) {
            min_val = col_sum[j];
        }
    }

    printf("%d\n", min_val);

    return 0;
}
